  var w = 800;
  var h = 280;

  var cx = 380;
  var ySurf = 80;
  var scale = 9.0;
  var yTip = ySurf + (hef * scale);
  var coneW = (1.5 * hef * scale);

  var svgContent = ''
    + '<!-- Concrete Block -->'
    + '<rect x="100" y="' + ySurf + '" width="600" height="170" fill="#1e293b" stroke="#475569" stroke-width="2" />'
