    + '<rect x="' + (cx - 15) + '" y="' + (yTip - 6) + '" width="30" height="12" fill="#38bdf8" rx="2" />'
    + '<text x="' + cx + '" y="' + (yTip + 20) + '" fill="#38bdf8" font-size="10" text-anchor="middle">Heavy Hex Head</text>'

    + '<!-- Baseplate -->'
