      '<polygon points="385,31 395,35 385,39" fill="#ef4444" />',
      '<text x="335" y="27" fill="#ef4444" font-size="11" font-weight="700">Hbase (Shear)</text>',

      '<!-- Vertical Gravity Load Vector (Vtotal) -->',
