    // Table rows
    document.getElementById('row_freq_ratio').textContent = freq_ratio.toFixed(3) + ' (f_s = ' + fs_hz.toFixed(1) + ' Hz, f_n = ' + fn_fluid.toFixed(1) + ' Hz)';
